import {VisuallyHidden} from '@primer/react'
import {Box, Heading} from '@primer/styled-react'
import {useState, useEffect} from 'react'
import capitalize from 'lodash-es/capitalize'
import {ErrorBoundary} from '@github-ui/react-core/error-boundary'

import {ChartCard} from '@github-ui/chart-card'

import {ErrorComponent, LoadingComponent, NoDataComponent} from '..'

import {RequestState, UsageGrouping, UsagePeriod} from '../../enums'
import {boxStyle} from '../../utils/style'
import {getPeriodText} from '../../utils'

import type {Filters, UsageChartData} from '../../types/usage'
import type {ReactNode} from 'react'

const containerStyle = {
  ...boxStyle,
  width: '100%',
  height: '100%',
  p: 0,
  mb: 3,
}

const chartHeaderContainerStyle = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'space-between',
  pl: 3,
  pr: 3,
  pt: 3,
}

const innerContainerStyle = {
  height: '432px',
  border: 0,
}

const chartSubtitleStyle = (showTitle: boolean) => {
  if (showTitle) {
    return {
      color: 'fg.muted',
      fontSize: '14px',
      fontWeight: 'normal',
    }
  } else {
    return {
      color: 'fg.muted',
      fontSize: '16px',
      fontWeight: 'bold',
    }
  }
}

function getChartTitle(filters: Filters, premiumRequestsVariant = false): string {
  let title = premiumRequestsVariant ? 'Usage' : 'Metered usage'
  let groupByType = ''

  switch (filters.group?.type) {
    case UsageGrouping.ORG: {
      groupByType = 'organizations'
      break
    }
    case UsageGrouping.REPO: {
      groupByType = 'repositories'
      break
    }
    case UsageGrouping.SKU: {
      groupByType = 'skus'
      break
    }
    case UsageGrouping.PRODUCT: {
      groupByType = 'products'
      break
    }
    case UsageGrouping.COSTCENTER: {
      groupByType = 'cost centers'
      break
    }
    case UsageGrouping.MODEL: {
      groupByType = 'models'
      break
    }
    case UsageGrouping.USER: {
      groupByType = 'users'
      break
    }
    case UsageGrouping.NONE: {
      if (premiumRequestsVariant) {
        title = 'Premium requests usage'
      }
      break
    }
  }

  // Only attempt to add filter data to the title text if it exists and has a filter value
  if (filters.searchQuery && filters.searchQuery.includes(':')) {
    let queryPartsTitleText = ''
    // Split by spaces, unless those spaces are in quotation marks, which is common for cost center names
    const queryParts = filters.searchQuery.match(/(?:[^\s"]+|"[^"]*")+/g) || []

    for (const queryPart of queryParts) {
      const [groupByField, groupByValue] = queryPart.split(':')

      if (!groupByField || !groupByValue) continue

      if (['repo', 'org', 'user'].includes(groupByField)) {
        queryPartsTitleText += `${groupByValue} `
      } else if (['product', 'sku'].includes(groupByField)) {
        queryPartsTitleText += `${capitalize(groupByValue)} `
      } else if (['cost_center'].includes(groupByField)) {
        // Cost center names with spaces will be in quotation marks, remove those if present at beginning and end
        if (groupByValue.startsWith('"') && groupByValue.endsWith('"')) {
          queryPartsTitleText += `${groupByValue.split('').slice(1, -1).join('')} `
        } else {
          queryPartsTitleText += `${groupByValue} `
        }
      } else if (['model'].includes(groupByField)) {
        queryPartsTitleText += `${groupByValue} `
      }
    }

    if (queryPartsTitleText) {
      if (filters.searchQuery.includes('user:')) {
        title = `${queryPartsTitleText.trim()}'s usage`
      } else {
        title = `${queryPartsTitleText} usage`
      }
    }
  }

  if (groupByType) title += ` grouped by ${groupByType}`

  return title
}

interface CustomPoint extends Highcharts.Point {
  custom?: {
    grossAmount?: string
    totalAmount?: string
    discountAmount?: string
  }
}

function tooltipPointFormatter(this: CustomPoint) {
  const grossAmount = this.custom?.grossAmount
  const totalAmount = this.custom?.totalAmount
  const discountAmount = this.custom?.discountAmount

  // eslint-disable-next-line github/unescaped-html-literal
  return `<tr><td style="padding-top:var(--base-size-4)"><span style="color:${this.color}">●</span> Gross:</td><td style="text-align: right; padding-top:var(--base-size-4);"><strong>${grossAmount}</strong></td></tr><tr><td style="padding-top:var(--base-size-4); padding-left:16px"> Billed:</td><td style="text-align: right; padding-top:var(--base-size-4);"><strong>${totalAmount}</strong></td></tr><tr><td style="padding-top:var(--base-size-4); padding-left:16px"> Discount:</td><td style="text-align: right; padding-top:var(--base-size-4);"><strong>${discountAmount}</strong></td></tr><table>`
}

function getChartPeriod(filters: Filters) {
  switch (filters.period?.type) {
    case UsagePeriod.THIS_YEAR:
    case UsagePeriod.LAST_YEAR: {
      return 30 * 24 * 3600 * 1000 // month
    }
    case UsagePeriod.THIS_MONTH:
    case UsagePeriod.LAST_MONTH: {
      return 24 * 3600 * 1000 // day
    }
    default: {
      return 24 * 3600 * 1000 // day
    }
  }
}

function getTooltipLabel(filters: Filters) {
  switch (filters.period?.type) {
    case UsagePeriod.THIS_YEAR:
    case UsagePeriod.LAST_YEAR: {
      return 'in %b %Y' // month
    }
    case UsagePeriod.THIS_MONTH:
    case UsagePeriod.LAST_MONTH: {
      return 'on %b %e, %Y' // day
    }
    default: {
      return '%b %e, %Y' // day
    }
  }
}

function getXAxisLabel(filters: Filters) {
  switch (filters.period?.type) {
    case UsagePeriod.THIS_YEAR:
    case UsagePeriod.LAST_YEAR: {
      return '{value:%b}' // month
    }
    case UsagePeriod.THIS_MONTH:
    case UsagePeriod.LAST_MONTH: {
      return '{value:%b %e}' // month day
    }
    default: {
      return '{value:%b %e}' // month day
    }
  }
}

interface UsageChartProps {
  filters: Filters
  requestState: RequestState
  usage: UsageChartData[]
  // Used to add children alongside the usage actions component.
  children?: ReactNode
  // Whether or not to show the chart title. The subtitle is always shown. Defaults to true
  showTitle?: boolean
  premiumRequestsVariant?: boolean
}

const isLoadingStates = new Set<RequestState>([RequestState.INIT, RequestState.LOADING])

// These values are defined by Highcharts, the library used for the ChartCard component.
// https://api.highcharts.com/class-reference/Highcharts#.DashStyleValue
const DASH_STYLES = [
  'Solid',
  'ShortDash',
  'ShortDot',
  'ShortDashDot',
  'ShortDashDotDot',
  'Dot',
  'Dash',
  'LongDash',
  'DashDot',
  'LongDashDot',
  'LongDashDotDot',
] as const

export function UsageChart({
  filters,
  requestState,
  usage,
  children,
  showTitle = true,
  premiumRequestsVariant = false,
}: UsageChartProps) {
  const [screenReaderAnnouncement, setScreenReaderAnnouncement] = useState<string>('')

  useEffect(() => {
    if (isLoadingStates.has(requestState)) {
      setScreenReaderAnnouncement('Loading usage data...')
    } else if (requestState === RequestState.ERROR) {
      setScreenReaderAnnouncement('Error loading usage data.')
    } else if (requestState === RequestState.IDLE) {
      if (!usage || usage.length === 0) {
        setScreenReaderAnnouncement('No usage data found for the selected filters.')
      } else {
        const title = getChartTitle(filters, premiumRequestsVariant)
        const period = filters.period?.displayText || 'selected period'
        const dataPoints = usage.reduce((sum, dataset) => sum + dataset.data.length, 0)
        setScreenReaderAnnouncement(`${title} chart showing data for ${period}. ${dataPoints} data points found.`)
      }
    }
  }, [requestState, usage, filters, premiumRequestsVariant])

  const usageLength = usage.length && usage[0]?.data?.length ? usage[0].data.length : 0
  const chartLoaded = requestState === RequestState.IDLE && usageLength > 0
  const usageChartStartDate = usage[0]?.data[0]?.x
  const usageData = usageLength ? usage[0]?.data : []
  const maxUsage = usageData ? usageData.reduce((max, point) => Math.max(max, point.y), 0) : 0

  return (
    <div data-hpc>
      <VisuallyHidden role="status">{screenReaderAnnouncement}</VisuallyHidden>
      <ErrorBoundary
        fallback={
          <div className="mb-3">
            <ChartCard size="xl" border>
              <ChartCard.Title sx={showTitle ? {} : chartSubtitleStyle(showTitle)}>
                {showTitle ? getChartTitle(filters, premiumRequestsVariant) : getPeriodText(filters.period)}
              </ChartCard.Title>
              {showTitle && <ChartCard.Description>{getPeriodText(filters.period)}</ChartCard.Description>}
              <ErrorComponent
                sx={innerContainerStyle}
                testid="usage-chart-error-boundary"
                text="Unable to load chart"
              />
            </ChartCard>
          </div>
        }
        appName="billing-app"
      >
        <Box sx={{pb: 2, display: ['block', 'none'], maxWidth: '100%'}}>{children}</Box>
        <Box sx={chartLoaded ? {} : containerStyle}>
          {!chartLoaded && (
            <Box sx={chartHeaderContainerStyle}>
              <div>
                {showTitle && (
                  <Heading as="h3" sx={{fontSize: 2}} id="usage-chart-title" data-testid="usage-chart-title">
                    {getChartTitle(filters, premiumRequestsVariant)}
                  </Heading>
                )}
                <Heading
                  as={showTitle ? 'h4' : 'h3'}
                  sx={chartSubtitleStyle(showTitle)}
                  id="usage-chart-subtitle"
                  data-testid="usage-chart-subtitle"
                  className={showTitle ? '' : 'h4'}
                >
                  {getPeriodText(filters.period)}
                </Heading>
              </div>
              <Box sx={{pr: 2, display: ['none', 'block']}}>{children}</Box>
            </Box>
          )}

          <div className="mb-3">
            {isLoadingStates.has(requestState) && (
              <LoadingComponent sx={innerContainerStyle} testid="usage-loading-spinner" />
            )}
            {requestState === RequestState.ERROR && (
              <ErrorComponent sx={innerContainerStyle} testid="usage-loading-error" text="Something went wrong" />
            )}
            {requestState === RequestState.IDLE && (
              <>
                {usageLength === 0 && (
                  <NoDataComponent sx={innerContainerStyle} testid="no-usage-data" text="No usage found" />
                )}
                {usageLength > 0 && (
                  <ChartCard size="xl" border>
                    <ChartCard.Title sx={showTitle ? {} : chartSubtitleStyle(showTitle)}>
                      {showTitle ? getChartTitle(filters, premiumRequestsVariant) : getPeriodText(filters.period)}
                    </ChartCard.Title>
                    {showTitle && <ChartCard.Description>{getPeriodText(filters.period)}</ChartCard.Description>}
                    <ChartCard.TrailingVisual>
                      <Box sx={{pr: 2, display: ['none', 'block']}}>{children}</Box>
                    </ChartCard.TrailingVisual>
                    <ChartCard.Chart
                      series={usage.map((dataset, index) => {
                        const baseDataset = {
                          ...dataset,
                          type: 'areaspline',
                        }
                        // Only apply different dash styles for premium requests variant
                        if (premiumRequestsVariant) {
                          return {
                            ...baseDataset,
                            // use modulo to ensure we don't go out of bounds and we cycle through DASH_STYLES array when needed.
                            dashStyle: DASH_STYLES[index % DASH_STYLES.length],
                          }
                        }
                        return baseDataset
                      })}
                      xAxisTitle={'Time'}
                      yAxisTitle={'Billing'}
                      xAxisOptions={{
                        type: 'datetime',
                        labels: {
                          format: getXAxisLabel(filters),
                        },
                        title: {
                          text: null,
                        },
                        gridLineDashStyle: 'Solid',
                      }}
                      yAxisOptions={{
                        labels: {
                          format: '${value:,.0f}',
                        },
                        gridLineDashStyle: 'Solid',
                        title: {
                          text: null,
                        },
                        tickInterval: maxUsage <= 1 ? 1 : undefined,
                      }}
                      plotOptions={{
                        series: {
                          pointStart: usageChartStartDate,
                          pointInterval: getChartPeriod(filters),
                          marker: {
                            enabled: usageLength === 1,
                          },
                        },
                      }}
                      type={'areaspline'}
                      overrideOptionsNotRecommended={{
                        legend: {
                          enabled: true,
                          margin: 16,
                          align: 'left',
                          layout: 'horizontal',
                          verticalAlign: 'top',
                          floating: false,
                          maxHeight: 64,
                        },
                        tooltip: {
                          dateTimeLabelFormats: {
                            millisecond: getTooltipLabel(filters),
                          },
                          // eslint-disable-next-line github/unescaped-html-literal
                          headerFormat: '<table><tr><th colspan="2">{series.name} {point.key}</th></tr>',
                          pointFormatter: tooltipPointFormatter,
                        },
                        accessibility: {keyboardNavigation: {order: ['legend', 'series']}},
                      }}
                    />
                  </ChartCard>
                )}
              </>
            )}
          </div>
        </Box>
      </ErrorBoundary>
    </div>
  )
}

export default UsageChart

try{ UsageChart.displayName ||= 'UsageChart' } catch {}